const rows=$input.all().map(item=>item.json);
const config=$('Digest Configuration').first().json;
const zone='America/Los_Angeles';
const ymd=d=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const today=ymd(new Date());
const matchesToday=v=>String(v??'').trim()===today;
const filtered=rows.filter(j=>{return matchesToday(j['First Seen At'])&&String(j.Link||'').trim()});
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const getUrl=j=>String(config.dashboardUrl||'').replace(/\/$/,'')+'?job='+encodeURIComponent(String(j.Link).trim());
const cleanText=s=>String(s??'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const description=s=>{const v=cleanText(s);return v.length>170?v.slice(0,167)+'…':v};
const score=j=>{const n=Number(String(j.Rating??'').trim());return Number.isFinite(n)?n:null;};
const sorted=filtered.sort((a,b)=>(score(b)??-1)-(score(a)??-1));
const isHigh=j=>score(j)>85;
const countHigh=sorted.filter(isHigh).length;

const runId=String($('When Called After Discovery').first().json.runId||'');
if(!runId)throw new Error('Missing runId from parent discovery workflow');
const matches=sorted.filter(j=>String(j['First Seen Run ID']||'')===runId);
const header='📋 Indeed discovery run finished ('+today+')\nNew jobs: '+matches.length+'\n\n';
const chunks=[];
let current=header;
for(const j of matches){
 const entry=String(j.Title||'Untitled job')+'\n'+String(j['Company Name']||'Unknown company')+' | '+String(j.Type||'Not specified')+'\nRating: '+(score(j)??'Pending')+'/100\n'+description(j['Job Description'])+'\nDashboard: '+getUrl(j)+'\n\n';
 if(current.length+entry.length>3400&&current!==header){chunks.push(current);current='📋 Discovery run (continued)\n\n'}
 current+=entry;
}
if(!matches.length)current+='No new jobs discovered in this run.';
chunks.push(current);
return chunks.map((telegramText,i)=>({json:{telegramText,chunk:i+1,totalChunks:chunks.length,runId,newJobs:matches.length}}));
